-radius:50%;background:var(--ink-2);position:absolute;left:-5.5px;top:21px;outline:4px solid var(--surface-hi)}.step.good::before{background:var(--like)}.step.bad::before{background:var(--dislike)}.step.waiting::before{background:var(--accent)}.step.selected{background:var(--accent-wash);border-color:var(--accent)}.step .content{color:var(--ink)}.step h3{margin:4px 0 8px}.step:last-child{padding-bottom:6px}.receipt{border-top:1px solid var(--line);margin-top:10px;font-size:var(--step--1)}.receipt>summary{cursor:pointer;padding:10px 0;color:var(--ink-2)}.receipt blockquote{margin:8px 0 12px;padding:0 12px;border-left:3px solid var(--like)}.receipt blockquote.wary{border-color:var(--dislike)}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:var(--step--1);margin:12px 0;font-variant-numeric:tabular-nums}.table th{font-weight:500;color:var(--muted);text-align:left}.table th,.table td{padding:9px 7px;border-bottom:1px solid var(--line)}.table .selected{background:var(--accent-wash)}.meter{height:4px;background:var(--surface-2);margin-top:5px;max-width:180px}.meter span{display:block;height:100%;background:var(--like)}.changes{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.empty{color:var(--muted);padding:20px 0}pre{max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font:12px var(--font-data)}.legend{gap:14px;font-size:var(--step--1);margin:12px 0}.history-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.history-person{padding:14px;border:1px solid var(--line);border-radius:8px}.history-person blockquote{margin:12px 0;padding-left:10px;border-left:2px solid var(--line);font-size:var(--step--1)}summary:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:700px){.controls{display:block}.controls label{margin:10px 0}.controls select{min-width:0;flex:1}.history-grid{grid-template-columns:1fr}.episode>summary .time{flex-basis:100%;padding-left:20px}.ti